def logos(ids,b):
 bounds=json.loads((R/'logo-layout.json').read_text(encoding='utf-8'))
 items=[]
 for i in ids:
  filename=f'client-{i}-hd.webp';info=bounds[filename];w,h=info['size'];x,y,x2,y2=info['box'];bw,bh=x2-x,y2-y
